INSERT INTO puestos (nombre_puesto, area, descripcion, nivel_experiencia, activo) VALUES
('Practicante de Desarrollo TI', 'Tecnología de la información', 'Práctica orientada al desarrollo de software y la resolución de problemas técnicos.', 'Practicante', TRUE),
('Soporte Técnico', 'Soporte y servicios TI', 'Práctica de diagnóstico de incidencias y comunicación de soluciones al usuario.', 'Inicial', TRUE),
('Atención al Cliente', 'Servicio al cliente', 'Práctica de escucha, atención de solicitudes y manejo de reclamos.', 'Inicial', TRUE);
INSERT INTO preguntas (id_puesto, enunciado, competencia_evaluada, orden, tiempo_limite_seg, activo, aplica_star) VALUES
((SELECT id_puesto FROM puestos WHERE nombre_puesto = 'Practicante de Desarrollo TI'), 'Preséntate brevemente y explica qué conocimientos o proyectos de tu formación puedes aportar como practicante de desarrollo.', 'Presentación y pertinencia profesional', 1, 60, TRUE, FALSE),
((SELECT id_puesto FROM puestos WHERE nombre_puesto = 'Practicante de Desarrollo TI'), 'Describe un problema que hayas encontrado en un proyecto académico o personal de software. Explica tu responsabilidad, qué hiciste y cuál fue el resultado o aprendizaje.', 'Resolución de problemas y responsabilidad', 2, 60, TRUE, TRUE),
((SELECT id_puesto FROM puestos WHERE nombre_puesto = 'Practicante de Desarrollo TI'), 'Si una funcionalidad deja de funcionar después de un cambio, ¿cómo investigarías la causa y comprobarías que tu corrección funciona?', 'Razonamiento técnico y verificación', 3, 60, TRUE, FALSE),
((SELECT id_puesto FROM puestos WHERE nombre_puesto = 'Soporte Técnico'), 'Un usuario indica que su computadora no tiene acceso a Internet. ¿Qué comprobaciones iniciales realizarías y en qué orden?', 'Diagnóstico técnico organizado', 1, 60, TRUE, FALSE),
((SELECT id_puesto FROM puestos WHERE nombre_puesto = 'Soporte Técnico'), 'Cuenta una ocasión en la que ayudaste a alguien a resolver una dificultad tecnológica, en estudios, trabajo o vida cotidiana. Explica qué hiciste y qué resultado obtuviste.', 'Resolución de incidencias y orientación al usuario', 2, 60, TRUE, TRUE),
((SELECT id_puesto FROM puestos WHERE nombre_puesto = 'Soporte Técnico'), '¿Cómo explicarías a una persona sin conocimientos técnicos para qué sirve una copia de seguridad y cómo comprobarías que entendió la explicación?', 'Comunicación técnica comprensible', 3, 60, TRUE, FALSE),
((SELECT id_puesto FROM puestos WHERE nombre_puesto = 'Atención al Cliente'), '¿Qué acciones concretas consideras importantes para brindar una buena atención y comprobar que entendiste la necesidad de una persona?', 'Escucha y orientación al cliente', 1, 60, TRUE, FALSE),
((SELECT id_puesto FROM puestos WHERE nombre_puesto = 'Atención al Cliente'), 'Describe una ocasión en la que atendiste una solicitud o desacuerdo de otra persona, en estudios, trabajo o una actividad grupal. Explica tu responsabilidad, cómo actuaste y el resultado.', 'Manejo de situaciones y responsabilidad', 2, 60, TRUE, TRUE),
((SELECT id_puesto FROM puestos WHERE nombre_puesto = 'Atención al Cliente'), 'Un cliente está molesto por una demora que no puedes solucionar de inmediato. ¿Cómo lo atenderías y qué alternativa concreta le ofrecerías?', 'Manejo de reclamos y comunicación', 3, 60, TRUE, FALSE);
